#include "data/kv_snapshot_codec.h"
#include <limits>
#include "data/wire_io.h"
namespace data {
namespace {
void PutVector(const std::vector<uint8_t>&v,std::vector<uint8_t>*o){wire::Put<uint64_t>(v.size(),o);wire::PutBytes(v.data(),v.size(),o);}
bool GetVector(const uint8_t**p,const uint8_t*e,uint64_t max,std::vector<uint8_t>*v){uint64_t n=0;if(!wire::Get(p,e,&n)||n>max||n>static_cast<uint64_t>(e-*p))return false;v->assign(*p,*p+n);*p+=n;return true;}
}
DataError EncodeKVSnapshot(const base::KVRequestSnapshot&s,std::vector<uint8_t>*o){if(!o||!o->empty()||s.schema_version!=1||s.block_size<=0||s.num_layers<=0||s.valid_tokens<0||s.committed_tokens<0||s.committed_tokens>s.valid_tokens||s.layers.size()!=static_cast<size_t>(s.num_layers))return DataError::kInvalidArgument;wire::Put<uint32_t>(kKVSnapshotMagic,o);wire::Put<uint16_t>(kKVSnapshotWireVersion,o);wire::Put<uint16_t>(0,o);wire::Put<uint64_t>(s.schema_version,o);wire::Put<uint32_t>(s.block_size,o);wire::Put<uint32_t>(s.num_layers,o);wire::Put<uint32_t>(s.valid_tokens,o);wire::Put<uint32_t>(s.committed_tokens,o);for(const auto&l:s.layers){wire::Put<uint32_t>(static_cast<uint32_t>(l.storage_mode),o);wire::Put<uint32_t>(static_cast<uint32_t>(l.storage_dtype),o);wire::Put<uint32_t>(static_cast<uint32_t>(l.scale_dtype),o);wire::Put<uint32_t>(0,o);wire::Put<uint64_t>(l.blocks.size(),o);for(const auto&b:l.blocks){PutVector(b.key,o);PutVector(b.value,o);PutVector(b.key_scale,o);PutVector(b.value_scale,o);}}return DataError::kOk;}
DataError DecodeKVSnapshot(const uint8_t*b,size_t n,uint64_t max,base::KVRequestSnapshot*out){if(!b||!out||n>max)return DataError::kInvalidArgument;const uint8_t*p=b,*e=b+n;uint32_t magic=0,bs=0,nl=0,vt=0,ct=0;uint16_t ver=0,res=0;base::KVRequestSnapshot s;if(!wire::Get(&p,e,&magic)||!wire::Get(&p,e,&ver)||!wire::Get(&p,e,&res)||!wire::Get(&p,e,&s.schema_version)||!wire::Get(&p,e,&bs)||!wire::Get(&p,e,&nl)||!wire::Get(&p,e,&vt)||!wire::Get(&p,e,&ct)||magic!=kKVSnapshotMagic||ver!=kKVSnapshotWireVersion||res!=0||s.schema_version!=1||bs==0||nl==0||nl>256||vt>10000000||ct>vt)return DataError::kInvalidArgument;s.block_size=static_cast<int32_t>(bs);s.num_layers=static_cast<int32_t>(nl);s.valid_tokens=static_cast<int32_t>(vt);s.committed_tokens=static_cast<int32_t>(ct);s.layers.resize(nl);uint64_t total=0;for(auto&l:s.layers){uint32_t mode=0,dtype=0,scale=0,pad=0;uint64_t blocks=0;if(!wire::Get(&p,e,&mode)||!wire::Get(&p,e,&dtype)||!wire::Get(&p,e,&scale)||!wire::Get(&p,e,&pad)||pad||!wire::Get(&p,e,&blocks)||blocks>1000000)return DataError::kInvalidArgument;l.storage_mode=static_cast<base::BlockStorageMode>(mode);l.storage_dtype=static_cast<base::DataType>(dtype);l.scale_dtype=static_cast<base::DataType>(scale);l.blocks.resize(blocks);for(auto&x:l.blocks){if(!GetVector(&p,e,max-total,&x.key))return DataError::kInvalidArgument;total+=x.key.size();if(!GetVector(&p,e,max-total,&x.value))return DataError::kInvalidArgument;total+=x.value.size();if(!GetVector(&p,e,max-total,&x.key_scale))return DataError::kInvalidArgument;total+=x.key_scale.size();if(!GetVector(&p,e,max-total,&x.value_scale))return DataError::kInvalidArgument;total+=x.value_scale.size();}}if(p!=e)return DataError::kInvalidArgument;*out=std::move(s);return DataError::kOk;}
}  // namespace data
